const WEB_VAULT_URL = `${ENV.FRONTEND_URL}/vault`;
const RESTRICTED_PAGE_REMEDY =
  "This browser page can't be filled. Open a sign-in page on a regular website, or enter the login manually.";
const UNAVAILABLE_PAGE_REMEDY =
  'Saved logins are unavailable right now. Enter the login manually, or focus the username or password field on a supported sign-in page and try Fill again.';
const NO_FOCUSED_LOGIN_REMEDY =
  'No login field is ready to fill. Enter the login manually, or focus the username or password field on a supported sign-in page and try Fill again.';

type Scope = 'mine' | 'shared';

/** What a row learns back from a confirmed removal: it unmounts only on `removed`. */
type VaultRemoval =
  | { status: 'removed' }
  | { status: 'cancelled' }
  | { status: 'failed'; message: string };

/**
 * Folds a `confirmDestructive` outcome and the hook method's failure sentence
 * into what a row needs. The `confirmDestructive` call itself stays at the
 * call site so the guard can see the operation inside its `run`.
 */
function vaultRemoval(confirmed: boolean, failure: string | null): VaultRemoval {
  if (!confirmed) return { status: 'cancelled' };
  if (failure) return { status: 'failed', message: failure };
  return { status: 'removed' };
}

export function VaultView() {
  const tab = useActiveTab();
  const pageUrl = tab.url;
  const { user } = useAuth();
  const organization = useActiveOrganization();
  const actor = useMemo(
    () =>
      user && organization.active
        ? { userId: user.id, organizationId: organization.active.id }
        : null,
    [organization.active, user],
  );
  // A new browsing/identity context owns a fresh component lifetime. Keying
  // the whole session also drops revealed values and edit forms immediately.
  const { owner, admission } = usePanelAdmission(tab.id, pageUrl, actor);
  return <VaultSession key={owner} tab={tab} actor={actor} admission={admission} />;
}

function VaultSession({
  tab,
  actor,
  admission,
}: {
  tab: ReturnType<typeof useActiveTab>;
  actor: { userId: string; organizationId: string } | null;
  admission: PanelActionAdmission;
}) {
  const pageUrl = tab.url;
  const panel = usePanelFill(tab.id, admission);
  const matchPageUrl = panel.status === 'ready' ? panel.pageUrl : pageUrl;
  const vault = useVault(matchPageUrl, tab.id, actor, admission);
  const login = useCredentialLogin(admission);
  const [scope, setScope] = useState<Scope>('mine');
  const [query, setQuery] = useState('');
  const [creating, setCreating] = useState(false);

  const host = useMemo(() => safeParseUrl(pageUrl)?.host ?? null, [pageUrl]);
  const fillable = isFillablePageUrl(pageUrl);
  const childOffer = panel.status === 'ready' && panel.frameId > 0;
  const panelUnavailable = panel.status === 'loading' || panel.status === 'unavailable';
  const siteMatches =
    panel.status === 'ready'
      ? panel.matches.filter((panelMatch) =>
          vault.matches.some((match) => match.item_id === panelMatch.item_id),
        )
      : vault.matches;

  const list = scope === 'mine' ? vault.mine : vault.shared;
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return list;
    return list.filter((item) => {
      const haystack = [item.display_name, ...item.login_urls, item.notes ?? '']
        .join(' ')
        .toLowerCase();
      return haystack.includes(q);
    });
  }, [list, query]);

  if (vault.auth === 'checking') {
    return (
      <div className="flex h-full items-center justify-center text-muted-foreground">
        <Loader2 className="size-4 animate-spin" />
      </div>
    );
  }

  if (vault.auth === 'signed-out') return <SignInPrompt />;

  return (
    <div className="flex h-full flex-col">
      <div className="flex h-9 shrink-0 items-center gap-1.5 px-2">
        <VaultIcon className="size-3.5 text-muted-foreground" />
        <span className="text-sm font-medium">Vault</span>
        <div className="ml-auto flex items-center gap-0.5">
          <IconButton
            title="Refresh"
            onClick={() => {
              void vault.reload();
            }}
          >
            <RefreshCw className={cn('size-3.5', vault.loading && 'animate-spin')} />
          </IconButton>
          <IconButton
            title="Open the full vault on the web"
            onClick={() => void chrome.tabs.create({ url: WEB_VAULT_URL })}
          >
            <ExternalLink className="size-3.5" />
          </IconButton>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <FillDeviceSetupCard />
        <PendingCaptureCard tabId={tab.id} onSaved={() => void vault.reload()} />
        <SiteSection
          key={tab.id ?? 'no-tab'}
          host={panel.status === 'ready' ? (safeParseUrl(panel.pageUrl)?.host ?? null) : host}
          allowAutomaticLogin={
            fillable && panel.status === 'ready' && !childOffer && login.supported
          }
          blockedReason={
            !fillable
              ? RESTRICTED_PAGE_REMEDY
              : panelUnavailable
                ? panel.status === 'loading'
                  ? 'Checking saved logins…'
                  : UNAVAILABLE_PAGE_REMEDY
                : panel.status === 'none'
                  ? NO_FOCUSED_LOGIN_REMEDY
                  : !login.supported && panel.status !== 'ready'
                    ? 'Browser login is not available in this browser yet.'
                    : null
          }
          pageUrl={matchPageUrl}
          matches={siteMatches}
          matchesLoading={panel.status === 'loading' || vault.matchesLoading}
          matchesError={vault.matchesError}
          running={login.running}
          outcome={!panelUnavailable && !childOffer ? login.outcome : null}
          panelStatus={panel.status}
          panelOutcome={!panelUnavailable ? panel.outcome : null}
          panelOutcomeHost={panel.outcomeHost}
          panelRunning={panel.running}
          panelItemIds={panel.itemIds}
          onFill={(id) => void panel.fill(id)}
          onUseHere={(id) => void login.useHere(id, tab.id)}
          onDismissOutcome={login.dismiss}
          onCreateFromPage={() => setCreating(true)}
          onRetryMatches={() => void vault.retryMatches()}
        />
        <PasswordGenerator tabId={tab.id} actor={actor} admission={admission} />

        {vault.error && (
          <div className="mx-2 mb-2 flex items-start gap-1.5 rounded-md border border-amber-500/40 bg-amber-500/10 px-2 py-1.5 text-xs">
            <AlertTriangle className="mt-0.5 size-3 shrink-0 text-amber-600 dark:text-amber-400" />
            <span className="text-muted-foreground">{vault.error}</span>
          </div>
        )}

        {creating && (
          <CreateLoginForm
            pageUrl={matchPageUrl}
            onCancel={() => setCreating(false)}
            onCreate={async (input) => {
              const error = await vault.createItem(input);
              if (!error) setCreating(false);
              return error;
            }}
          />
        )}

        <div className="flex items-center gap-1.5 px-2 pb-1.5">
          <div className="relative flex-1">
            <Search className="absolute left-2 top-1/2 size-3 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search logins"
              className="h-7 pl-6 text-xs"
            />
          </div>
          {!creating && (
            <Button size="sm" className="h-7 gap-1 px-2 text-xs" onClick={() => setCreating(true)}>
              <Plus className="size-3" /> New
            </Button>
          )}
        </div>

        <div className="px-2 pb-1.5">
          <Tabs value={scope} onValueChange={(v) => setScope(v as Scope)}>
            <TabsList className="h-7 w-full">
              <TabsTrigger value="mine" className="h-6 flex-1 text-xs">
                Mine ({vault.mine.length})
              </TabsTrigger>
              <TabsTrigger value="shared" className="h-6 flex-1 text-xs">
                Shared ({vault.shared.length})
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>

        {vault.loading && list.length === 0 ? (
          <div className="flex h-20 items-center justify-center text-muted-foreground">
            <Loader2 className="size-4 animate-spin" />
          </div>
        ) : filtered.length === 0 ? (
          <p className="px-3 py-6 text-center text-xs text-muted-foreground">
            {list.length === 0
              ? scope === 'mine'
                ? 'No logins saved yet.'
                : 'Nobody has shared a login with you.'
              : 'No logins match that search.'}
          </p>
        ) : (
          <ul className="space-y-1 px-2 pb-3">
            {filtered.map((item) => (
              <ItemRow
                key={item.id}
                item={item}
                pageUrl={pageUrl}
                onPatch={(patch) => vault.patchItem(item.id, patch)}
                onChangeValue={(fieldId, value) => vault.changeFieldValue(item.id, fieldId, value)}
                onAddField={(field) => vault.addField(item.id, field)}
                onRemoveField={async (fieldId) => {
                  const field = item.fields.find((f) => f.id === fieldId);
                  let failure: string | null = null;
                  const confirmed = await confirmDestructive({
                    title: `Remove the field "${field?.field_key || 'this field'}" from "${item.display_name}"?`,
                    consequence:
                      'The field and its saved value are deleted from the Vault on the server, for everyone this login is shared with. This cannot be undone.',
                    confirmLabel: 'Remove field',
                    run: async () => {
                      failure = await vault.removeVaultField(item.id, fieldId);
                    },
                  });
                  return vaultRemoval(confirmed, failure);
                }}
                onRemove={async () => {
                  let failure: string | null = null;
                  const confirmed = await confirmDestructive({
                    title: `Delete the login "${item.display_name}"?`,
                    consequence: `The login and every one of its ${item.fields.length} saved ${item.fields.length === 1 ? 'field' : 'fields'} are deleted from the Vault on the server, for everyone it is shared with. This cannot be undone from the extension — it can be restored from the AI Matrx Trash.`,
                    alternative:
                      'To stop the browser filling it without losing it, cancel and turn off "Fill in browser" on the login instead.',
                    confirmLabel: 'Delete login',
                    run: async () => {
                      failure = await vault.removeVaultItem(item.id);
                    },
                  });
                  return vaultRemoval(confirmed, failure);
                }}
              />
            ))}
          </ul>
        )}

        <p className="px-3 pb-4 text-[11px] leading-relaxed text-muted-foreground">
          Sharing, transfer, ownership, and file attachments live in the full vault on the web.
        </p>
      </div>
    </div>
  );
}

// ── Sign-in gate ────────────────────────────────────────────────────────────

/**
 * The extension's guest identity is a fingerprint, and the Vault rejects it by
 * design. Say that plainly instead of showing an empty list.
 */
function SignInPrompt() {
  const { signIn, status } = useAuth();
  return (
    <div className="flex h-full flex-col items-center justify-center gap-3 px-6 text-center">
      <ShieldCheck className="size-6 text-muted-foreground" />
      <p className="text-sm font-medium">Sign in to open your Vault</p>
      <p className="text-xs leading-relaxed text-muted-foreground">
        Saved logins are only ever released to a signed-in Matrx account. Guest sessions cannot
        reach them.
      </p>
      <Button
        size="sm"
        className="h-7 gap-1 px-3 text-xs"
        onClick={signIn}
        disabled={status === 'signing-in'}
      >
        {status === 'signing-in' ? (
          <Loader2 className="size-3 animate-spin" />
        ) : (
          <LogIn className="size-3" />
        )}
        Sign in
      </Button>
    </div>
  );
}

// ── "Logins for this site" ──────────────────────────────────────────────────

interface SiteSectionProps {
  host: string | null;
  /** Null when fill is possible here; otherwise the exact reason it is not. */
  blockedReason: string | null;
  pageUrl: string | null;
  matches: { item_id: string; display_name: string }[];
  matchesLoading: boolean;
  matchesError: VaultCallFailure | null;
  running: string | null;
  outcome: { status: string; message: string } | null;
  panelStatus: PanelSavedLoginSnapshot['status'];
  allowAutomaticLogin: boolean;
  panelOutcome: string | null;
  panelOutcomeHost: string | null;
  panelRunning: string | null;
  panelItemIds: string[];
  onFill: (itemId: string) => void;
  onUseHere: (itemId: string) => void;
  onDismissOutcome: () => void;
  onCreateFromPage: () => void;
  onRetryMatches: () => void;
}

export function SiteSection(props: SiteSectionProps) {
  const { host, blockedReason, matches, matchesLoading, matchesError, running, outcome } = props;
  const good = outcome?.status === 'authenticated' || outcome?.status === 'needs_mfa';

  return (
    <div className="border-b bg-muted/30 px-2 py-2">
      <div className="mb-1.5 flex items-center gap-1.5 text-xs">
        <Globe className="size-3 shrink-0 text-muted-foreground" />
        <span className="truncate font-medium">{host ?? 'No page open'}</span>
        {matchesLoading && <Loader2 className="size-3 animate-spin text-muted-foreground" />}
      </div>

      {matchesError ? (
        <div className="flex items-center justify-between gap-2">
          <p className="text-[11px] text-muted-foreground">{describeVaultFailure(matchesError)}</p>
          <Button
            size="sm"
            variant="outline"
            className="h-6 gap-1 px-2 text-[11px]"
            disabled={matchesLoading}
            onClick={props.onRetryMatches}
          >
            {matchesLoading ? (
              <Loader2 className="size-3 animate-spin" />
            ) : (
              <RefreshCw className="size-3" />
            )}
            Retry
          </Button>
        </div>
      ) : matchesLoading ? (
        <p className="text-[11px] text-muted-foreground">Checking saved logins…</p>
      ) : blockedReason !== null ? (
        <p className="text-[11px] text-muted-foreground">{blockedReason}</p>
      ) : matches.length === 0 ? (
        <div className="flex items-center justify-between gap-2">
          <p className="text-[11px] text-muted-foreground">No saved login fills this page.</p>
          <Button
            size="sm"
            variant="outline"
            className="h-6 gap-1 px-2 text-[11px]"
            onClick={props.onCreateFromPage}
          >
            <Plus className="size-3" /> Save this site
          </Button>
        </div>
      ) : (
        <ul className="space-y-1">
          {matches.map((match) => {
            const label = captureUpdateTargetLabel(match, matches);
            return (
              <li
                key={match.item_id}
                className="flex items-center gap-2 rounded-md border bg-background px-2 py-1"
              >
                <span className="min-w-0 flex-1 truncate text-xs">
                  {label.primary}
                  {label.secondary && (
                    <span className="text-muted-foreground"> · {label.secondary}</span>
                  )}
                </span>
                {props.panelStatus === 'ready' && props.panelItemIds.includes(match.item_id) && (
                  <Button
                    size="sm"
                    className="h-6 px-2 text-[11px]"
                    disabled={running !== null || props.panelRunning !== null}
                    onClick={() => props.onFill(match.item_id)}
                  >
                    {props.panelRunning === match.item_id ? (
                      <Loader2 className="size-3 animate-spin" />
                    ) : (
                      'Fill'
                    )}
                  </Button>
                )}
                {props.allowAutomaticLogin && (
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-6 px-2 text-[11px]"
                    disabled={running !== null || props.panelRunning !== null}
                    onClick={() => props.onUseHere(match.item_id)}
                  >
                    {running === match.item_id ? (
                      <Loader2 className="size-3 animate-spin" />
                    ) : (
                      'Sign in'
                    )}
                  </Button>
                )}
              </li>
            );
          })}
        </ul>
      )}

      {outcome && (
        <div
          className={cn(
            'mt-1.5 flex items-start gap-1.5 rounded-md border px-2 py-1 text-[11px]',
            good
              ? 'border-emerald-500/40 bg-emerald-500/10'
              : 'border-amber-500/40 bg-amber-500/10',
          )}
        >
          {good ? (
            <Check className="mt-0.5 size-3 shrink-0 text-emerald-600 dark:text-emerald-400" />
          ) : (
            <AlertTriangle className="mt-0.5 size-3 shrink-0 text-amber-600 dark:text-amber-400" />
          )}
          <span className="flex-1 text-muted-foreground">{outcome.message}</span>
          <button
            type="button"
            onClick={props.onDismissOutcome}
            className="text-muted-foreground hover:text-foreground"
            title="Dismiss"
          >
            <X className="size-3" />
          </button>
        </div>
      )}
      {props.panelStatus === 'disabled' && (
        <p className="mt-1.5 text-[11px] text-muted-foreground">
          Turn on saved-login matching in extension settings to use Fill.
        </p>
      )}
      {props.panelStatus === 'none' && blockedReason === null && !outcome && (
        <p className="mt-1.5 text-[11px] text-muted-foreground">
          Click the username or password box on the website, then choose Fill.
        </p>
      )}
      {props.panelOutcome && (
        <div className="mt-1.5 text-[11px] text-muted-foreground">
          {props.panelOutcomeHost && <span>{props.panelOutcomeHost}</span>}
          <p>{props.panelOutcome}</p>
        </div>
      )}
    </div>
  );
}

function usePanelFill(
  tabId: number | null,
  admission: PanelActionAdmission,
): {
  running: string | null;
  outcome: string | null;
  outcomeHost: string | null;
  fill: (itemId: string) => Promise<void>;
} & PanelSavedLoginSnapshot {
  const [snapshot, setSnapshot] = useState<PanelSavedLoginSnapshot>({
    status: 'loading',
    itemIds: [],
  });
  const [running, setRunning] = useState<string | null>(null);
  const [outcome, setOutcome] = useState<string | null>(null);
  const [outcomeHost, setOutcomeHost] = useState<string | null>(null);
  const mounted = useRef(false);
  useLayoutEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  useEffect(() => {
    let live = true;
    let request = 0;
    setOutcome(null);
    setOutcomeHost(null);
    setRunning(null);
    setSnapshot({ status: 'loading', itemIds: [] });
    const read = (): void => {
      if (tabId == null) return;
      const ticket = ++request;
      setSnapshot({ status: 'loading', itemIds: [] });
      void chrome.runtime
        .sendMessage({
          __matrx: true,
          kind: 'credential-suggestions:panel-status',
          payload: { tabId },
        })
        .then((value: unknown) => {
          if (!admission.current() || !mounted.current || !live || ticket !== request) return;
          const next = parsePanelSavedLoginStatus(value);
          setSnapshot(next);
          if (next.status === 'unavailable') {
            setOutcome(null);
            setOutcomeHost(null);
          }
        })
        .catch(() => {
          if (admission.current() && mounted.current && live && ticket === request) {
            setSnapshot({ status: 'unavailable', itemIds: [] });
            setOutcome(null);
            setOutcomeHost(null);
          }
        });
    };
    read();
    const listener = (message: unknown): void => {
      const env = message as { __matrx?: unknown; kind?: unknown; payload?: { tabId?: unknown } };
      if (
        env?.__matrx === true &&
        env.kind === 'credential-assistance:changed' &&
        env.payload?.tabId === tabId
      )
        read();
    };
    chrome.runtime.onMessage.addListener(listener);
    return () => {
      live = false;
      chrome.runtime.onMessage.removeListener(listener);
    };
  }, [admission, tabId]);
  const fill = useCallback(
    async (itemId: string) => {
      if (
        tabId == null ||
        running !== null ||
        snapshot.status !== 'ready' ||
        !snapshot.itemIds.includes(itemId)
      )
        return;
      if (!mounted.current || !admission.current()) return;
      let started = false;
      await admission.run(async () => {
        started = true;
        setRunning(itemId);
        setOutcome(null);
        setOutcomeHost(safeParseUrl(snapshot.pageUrl)?.host ?? null);
        try {
          const result = (await chrome.runtime.sendMessage({
            __matrx: true,
            kind: 'credential-suggestions:panel-fill',
            payload: { tabId, offerId: snapshot.offerId, itemId },
          })) as { status?: unknown };
          if (!mounted.current || !admission.current()) return;
          setOutcome(
            result?.status === 'filled'
              ? 'Filled. Review the form, then sign in.'
              : result?.status === 'partial_manual_check'
                ? 'Matrx could not fully restore the login fields. Review them before signing in.'
                : result?.status === 'stale'
                  ? 'Click the username or password box on the website, then choose Fill.'
                  : 'Saved logins are unavailable right now.',
          );
        } catch {
          if (mounted.current && admission.current())
            setOutcome('Saved logins are unavailable right now.');
        } finally {
          if (mounted.current && admission.current()) {
            setRunning(null);
            setSnapshot((current) =>
              current.status === 'ready' && current.offerId === snapshot.offerId
                ? { status: 'none', itemIds: [] }
                : current,
            );
          }
        }
      });
      if (!started && mounted.current && admission.current()) {
        setOutcomeHost(null);
        setOutcome('Could not start filling. Focus the login field, then try Fill again.');
      }
    },
    [admission, running, snapshot, tabId],
  );
  return { ...snapshot, running, outcome, outcomeHost, fill };
}

// ── One saved login ─────────────────────────────────────────────────────────

interface ItemRowProps {
  item: VaultItemSummary;
  pageUrl: string | null;
  onPatch: (patch: VaultItemMetadataPatch) => Promise<string | null>;
  onChangeValue: (fieldId: string, value: string) => Promise<string | null>;
  onAddField: (field: VaultFieldInput) => Promise<string | null>;
  onRemoveField: (fieldId: string) => Promise<VaultRemoval>;
  onRemove: () => Promise<VaultRemoval>;
}

function ItemRow({
  item,
  pageUrl,
  onPatch,
  onChangeValue,
  onAddField,
  onRemoveField,
  onRemove,
}: ItemRowProps) {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [addingField, setAddingField] = useState(false);

  const mode = asUriMatchMode(item.uri_match_mode);
  const host = primaryHost(item.login_urls);
  const normalizedPage = normalizeLoginUrl(pageUrl);
  const alreadyCovers = coversPage(item.login_urls, mode, pageUrl);
  const canEdit = item.capabilities.can_edit;
  const canManage = item.capabilities.can_manage;
  const canAddPage =
    canEdit && normalizedPage !== null && isFillablePageUrl(pageUrl) && !alreadyCovers;

  const run = useCallback(
    async (patch: VaultItemMetadataPatch) => {
      setBusy(true);
      setError(await onPatch(patch));
      setBusy(false);
    },
    [onPatch],
  );

  const remove = useCallback(async () => {
    setBusy(true);
    const outcome = await onRemove();
    // On success this row unmounts — only touch state otherwise.
    if (outcome.status !== 'removed') {
      if (outcome.status === 'failed') setError(outcome.message);
      setBusy(false);
    }
  }, [onRemove]);

  return (
    <li className="rounded-md border bg-card">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center gap-1.5 px-2 py-1.5 text-left"
      >
        {open ? (
          <ChevronDown className="size-3 shrink-0 text-muted-foreground" />
        ) : (
          <ChevronRight className="size-3 shrink-0 text-muted-foreground" />
        )}
        <span className="min-w-0 flex-1">
          <span className="block truncate text-xs font-medium">{item.display_name}</span>
          <span className="block truncate text-[11px] text-muted-foreground">
            {host ?? 'No site set'}
          </span>
        </span>
        {item.browser_fill_enabled ? (
          <Badge variant="secondary" className="h-4 shrink-0 px-1 text-[10px]">
            Fill on
          </Badge>
        ) : (
          <Badge variant="outline" className="h-4 shrink-0 px-1 text-[10px] text-muted-foreground">
            Fill off
          </Badge>
        )}
      </button>

      {open && (
        <div className="space-y-2 border-t px-2 py-2">
          {editing ? (
            <EditDetailsForm
              item={item}
              busy={busy}
              onCancel={() => setEditing(false)}
              onSave={async (patch) => {
                setBusy(true);
                const failure = await onPatch(patch);
                setBusy(false);
                setError(failure);
                if (!failure) setEditing(false);
              }}
            />
          ) : (
            <>
              {item.fields.length === 0 ? (
                <p className="text-[11px] text-muted-foreground">This item has no fields.</p>
              ) : (
                <ul className="space-y-1">
                  {item.fields
                    .filter((field) => field.is_active)
                    .map((field) => (
                      <FieldRow
                        key={field.id || field.field_key}
                        itemId={item.id}
                        field={field}
                        canReveal={item.capabilities.can_reveal}
                        canEdit={canEdit}
                        onChangeValue={(value) => onChangeValue(field.id, value)}
                        onRemove={() => onRemoveField(field.id)}
                      />
                    ))}
                </ul>
              )}

              {addingField ? (
                <AddFieldForm
                  existingKeys={item.fields.map((f) => f.field_key)}
                  onCancel={() => setAddingField(false)}
                  onAdd={async (field) => {
                    const failure = await onAddField(field);
                    if (!failure) setAddingField(false);
                    return failure;
                  }}
                />
              ) : (
                canEdit && (
                  <button
                    type="button"
                    className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground"
                    onClick={() => setAddingField(true)}
                  >
                    <Plus className="size-3" /> Add a field
                  </button>
                )
              )}

              <div className="flex items-center justify-between gap-2 rounded-md bg-muted/40 px-2 py-1">
                <span className="text-[11px]">Browser fill</span>
                <Switch
                  checked={item.browser_fill_enabled}
                  disabled={busy || !canEdit}
                  onCheckedChange={(checked) => void run({ browser_fill_enabled: checked })}
                />
              </div>

              {item.login_urls.length > 0 && (
                <ul className="space-y-0.5">
                  {item.login_urls.map((url) => (
                    <li key={url} className="truncate text-[11px] text-muted-foreground">
                      {loginUrlLabel(url)}
                    </li>
                  ))}
                </ul>
              )}

              {item.notes && (
                <p className="whitespace-pre-wrap break-words text-[11px] text-muted-foreground">
                  {item.notes}
                </p>
              )}

              {canAddPage && (
                <Button
                  size="sm"
                  variant="outline"
                  className="h-6 w-full gap-1 px-2 text-[11px]"
                  disabled={busy}
                  onClick={() =>
                    void run({
                      login_urls: withPageAdded(item.login_urls, pageUrl),
                      browser_fill_enabled: true,
                    })
                  }
                >
                  {busy ? <Loader2 className="size-3 animate-spin" /> : <Plus className="size-3" />}
                  Use this login on {safeParseUrl(pageUrl)?.host ?? 'this page'}
                </Button>
              )}

              {alreadyCovers && (
                <p className="text-[11px] text-muted-foreground">
                  This page is already covered ({mode === 'exact' ? 'exact URL' : 'whole site'}).
                </p>
              )}
            </>
          )}

          {error && <p className="text-[11px] text-amber-600 dark:text-amber-400">{error}</p>}

          {!editing && (
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
              {canEdit && (
                <button
                  type="button"
                  className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground"
                  onClick={() => setEditing(true)}
                >
                  <Pencil className="size-3" /> Edit details
                </button>
              )}
              {canManage && (
                <button
                  type="button"
                  className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-destructive disabled:opacity-50"
                  disabled={busy}
                  onClick={() => void remove()}
                >
                  <Trash2 className="size-3" /> {busy ? 'Deleting…' : 'Delete'}
                </button>
              )}
              <button
                type="button"
                className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground"
                onClick={() =>
                  void chrome.tabs.create({
                    url: `${WEB_VAULT_URL}?item=${encodeURIComponent(item.id)}`,
                  })
                }
              >
                <ExternalLink className="size-3" /> Share &amp; more on the web
              </button>
            </div>
          )}
        </div>
      )}
    </li>
  );
}

// ── Edit name / site URLs / match mode / notes ──────────────────────────────

const MATCH_MODE_LABEL: Record<UriMatchMode, string> = {
  host: 'Whole site',
  exact: 'Exact URL only',
  never: 'Never match',
};

function EditDetailsForm({
  item,
  busy,
  onCancel,
  onSave,
}: {
  item: VaultItemSummary;
  busy: boolean;
  onCancel: () => void;
  onSave: (patch: VaultItemMetadataPatch) => Promise<void>;
}) {
  const [name, setName] = useState(item.display_name);
  const [urlsText, setUrlsText] = useState(item.login_urls.join('\n'));
  const [mode, setMode] = useState<UriMatchMode>(asUriMatchMode(item.uri_match_mode));
  const [notes, setNotes] = useState(item.notes ?? '');
  const [urlError, setUrlError] = useState<string | null>(null);
  const ids = useId();

  const submit = useCallback(async () => {
    const urls: string[] = [];
    for (const line of urlsText.split('\n')) {
      const raw = line.trim();
      if (!raw) continue;
      const normalized = normalizeLoginUrl(raw);
      // Same rule as the tool: https anywhere, http only on loopback.
      if (!normalized || !isFillablePageUrl(raw)) {
        setUrlError(`"${raw}" is not an https address, so it cannot be a login URL.`);
        return;
      }
      if (!urls.includes(normalized)) urls.push(normalized);
    }
    setUrlError(null);
    const patch: VaultItemMetadataPatch = {
      display_name: name.trim() || item.display_name,
      login_urls: urls,
      uri_match_mode: mode,
      notes,
    };
    // Fill cannot stay on with nowhere to fill.
    if (urls.length === 0 && item.browser_fill_enabled) patch.browser_fill_enabled = false;
    await onSave(patch);
  }, [item.browser_fill_enabled, item.display_name, mode, name, notes, onSave, urlsText]);

  return (
    <div className="space-y-1.5">
      <label htmlFor={`${ids}-name`} className="block text-[11px] text-muted-foreground">
        Name
        <Input
          id={`${ids}-name`}
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="mt-0.5 h-7 text-xs"
        />
      </label>
      <label htmlFor={`${ids}-urls`} className="block text-[11px] text-muted-foreground">
        Login URLs (one per line, https only)
        <Textarea
          id={`${ids}-urls`}
          value={urlsText}
          onChange={(e) => setUrlsText(e.target.value)}
          rows={2}
          className="mt-0.5 min-h-0 px-2 py-1 font-mono text-[11px]"
          placeholder="https://example.com/login"
        />
      </label>
      <label htmlFor={`${ids}-mode`} className="block text-[11px] text-muted-foreground">
        Match rule
        <select
          id={`${ids}-mode`}
          value={mode}
          onChange={(e) => setMode(asUriMatchMode(e.target.value))}
          className="mt-0.5 h-7 w-full rounded-md border border-input bg-transparent px-2 text-xs"
        >
          {(Object.keys(MATCH_MODE_LABEL) as UriMatchMode[]).map((m) => (
            <option key={m} value={m}>
              {MATCH_MODE_LABEL[m]}
            </option>
          ))}
        </select>
      </label>
      <label htmlFor={`${ids}-notes`} className="block text-[11px] text-muted-foreground">
        Notes — not encrypted. Never put a password or code here.
        <Textarea
          id={`${ids}-notes`}
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={2}
          className="mt-0.5 min-h-0 px-2 py-1 text-[11px]"
        />
      </label>
      {urlError && <p className="text-[11px] text-amber-600 dark:text-amber-400">{urlError}</p>}
      <div className="flex gap-1.5">
        <Button
          size="sm"
          className="h-7 flex-1 text-xs"
          disabled={busy}
          onClick={() => void submit()}
        >
          {busy ? <Loader2 className="size-3 animate-spin" /> : 'Save'}
        </Button>
        <Button
          size="sm"
          variant="outline"
          className="h-7 px-2 text-xs"
          disabled={busy}
          onClick={onCancel}
        >
          Cancel
        </Button>
      </div>
    </div>
  );
}

// ── Add one encrypted field ─────────────────────────────────────────────────

const FIELD_KEY_RE = /^[a-z][a-z0-9_]*$/;

function AddFieldForm({
  existingKeys,
  onCancel,
  onAdd,
}: {
  existingKeys: string[];
  onCancel: () => void;
  onAdd: (field: VaultFieldInput) => Promise<string | null>;
}) {
  const [key, setKey] = useState('');
  const [value, setValue] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const normalizedKey = key
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');
  const keyOk = FIELD_KEY_RE.test(normalizedKey) && !existingKeys.includes(normalizedKey);

  const submit = useCallback(async () => {
    setBusy(true);
    setError(null);
    const failure = await onAdd({ field_key: normalizedKey, value, handling: 'revealable' });
    // Drop the plaintext the moment the request resolves, whatever the outcome.
    setValue('');
    setBusy(false);
    if (failure) setError(failure);
  }, [normalizedKey, onAdd, value]);

  return (
    <div className="space-y-1.5 rounded-md bg-muted/40 p-2">
      <Input
        value={key}
        onChange={(e) => setKey(e.target.value)}
        placeholder="Field name (e.g. security_answer)"
        className="h-7 text-xs"
      />
      <Input
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="Value"
        type="password"
        autoComplete="new-password"
        className="h-7 text-xs"
      />
      {key && !keyOk && (
        <p className="text-[11px] text-muted-foreground">
          {existingKeys.includes(normalizedKey)
            ? 'That field already exists on this login.'
            : 'Use letters, numbers, and underscores, starting with a letter.'}
        </p>
      )}
      {error && <p className="text-[11px] text-amber-600 dark:text-amber-400">{error}</p>}
      <div className="flex gap-1.5">
        <Button
          size="sm"
          className="h-7 flex-1 text-xs"
          disabled={!keyOk || value.length === 0 || busy}
          onClick={() => void submit()}
        >
          {busy ? <Loader2 className="size-3 animate-spin" /> : 'Add field'}
        </Button>
        <Button size="sm" variant="outline" className="h-7 px-2 text-xs" onClick={onCancel}>
          Cancel
        </Button>
      </div>
    </div>
  );
}

// ── One field, masked until explicitly revealed ─────────────────────────────

function FieldRow({
  itemId,
  field,
  canReveal,
  canEdit,
  onChangeValue,
  onRemove,
}: {
  itemId: string;
  field: VaultFieldSummary;
  canReveal: boolean;
  canEdit: boolean;
  onChangeValue: (value: string) => Promise<string | null>;
  onRemove: () => Promise<VaultRemoval>;
}) {
  const secret = useTransientSecret();
  const [busy, setBusy] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [changing, setChanging] = useState(false);
  const [draft, setDraft] = useState('');

  const sealed = field.handling === 'sealed';
  const revealable = canReveal && !sealed;
  // Any authorized editor may replace a value, sealed included — replacing is
  // the ONLY way to change a sealed value, since it can never be shown.
  const editable = canEdit && field.id.length > 0;

  const reveal = useCallback(async () => {
    if (secret.value !== null) {
      secret.clear();
      return;
    }
    setBusy(true);
    setError(null);
    // Imported lazily so the reveal route is only pulled in when a human
    // actually asks for a value.
    const { revealVaultField, describeVaultFailure } = await import('@/lib/api/routes/vault');
    const result = await revealVaultField(itemId, field.field_key);
    setBusy(false);
    if (!result.ok) {
      setError(describeVaultFailure(result.failure));
      return;
    }
    secret.hold(result.data);
  }, [field.field_key, itemId, secret]);

  const copy = useCallback(async () => {
    setBusy(true);
    setError(null);
    const { revealVaultField, describeVaultFailure } = await import('@/lib/api/routes/vault');
    // Reveal fresh rather than reading whatever is on screen — the value may
    // have already auto-cleared, and re-fetching keeps the audit honest.
    const result = await revealVaultField(itemId, field.field_key);
    setBusy(false);
    if (!result.ok) {
      setError(describeVaultFailure(result.failure));
      return;
    }
    const ok = await copyToClipboard(result.data);
    setCopied(ok);
    setError(ok ? null : 'Could not reach the clipboard.');
    setTimeout(() => setCopied(false), 2000);
  }, [field.field_key, itemId]);

  const saveNewValue = useCallback(async () => {
    setBusy(true);
    setError(null);
    secret.clear();
    const failure = await onChangeValue(draft);
    // Drop the plaintext the moment the request resolves, whatever the outcome.
    setDraft('');
    setBusy(false);
    if (failure) {
      setError(failure);
      return;
    }
    setChanging(false);
  }, [draft, onChangeValue, secret]);

  const remove = useCallback(async () => {
    setBusy(true);
    const outcome = await onRemove();
    // On success this row unmounts — only touch state otherwise.
    if (outcome.status !== 'removed') {
      if (outcome.status === 'failed') setError(outcome.message);
      setBusy(false);
    }
  }, [onRemove]);

  return (
    <li className="rounded-md bg-muted/40 px-2 py-1">
      <div className="flex items-center gap-1.5">
        <span className="w-20 shrink-0 truncate text-[11px] text-muted-foreground">
          {field.field_key}
        </span>
        {changing ? (
          <Input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="New value"
            type="password"
            autoComplete="new-password"
            autoFocus
            disabled={busy}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && draft.length > 0) void saveNewValue();
              if (e.key === 'Escape') {
                setDraft('');
                setChanging(false);
              }
            }}
            className="h-6 min-w-0 flex-1 font-mono text-[11px]"
          />
        ) : (
          <span className="min-w-0 flex-1 truncate font-mono text-[11px]">
            {secret.value ?? field.value_hint ?? '••••••'}
          </span>
        )}
        {changing ? (
          <>
            <IconButton
              title="Save new value"
              onClick={() => void saveNewValue()}
              disabled={busy || draft.length === 0}
            >
              {busy ? <Loader2 className="size-3 animate-spin" /> : <Check className="size-3" />}
            </IconButton>
            <IconButton
              title="Cancel"
              onClick={() => {
                setDraft('');
                setChanging(false);
              }}
              disabled={busy}
            >
              <X className="size-3" />
            </IconButton>
          </>
        ) : (
          <>
            {revealable && (
              <>
                <IconButton
                  title={secret.value ? 'Hide' : 'Reveal'}
                  onClick={() => void reveal()}
                  disabled={busy}
                >
                  {busy ? (
                    <Loader2 className="size-3 animate-spin" />
                  ) : secret.value ? (
                    <EyeOff className="size-3" />
                  ) : (
                    <Eye className="size-3" />
                  )}
                </IconButton>
                <IconButton title="Copy" onClick={() => void copy()} disabled={busy}>
                  {copied ? (
                    <Check className="size-3 text-emerald-500" />
                  ) : (
                    <Copy className="size-3" />
                  )}
                </IconButton>
              </>
            )}
            {editable && (
              <>
                <IconButton
                  title="Change value"
                  onClick={() => {
                    setChanging(true);
                  }}
                  disabled={busy}
                >
                  <Pencil className="size-3" />
                </IconButton>
                <IconButton title="Remove field" onClick={() => void remove()} disabled={busy}>
                  <Trash2 className="size-3" />
                </IconButton>
              </>
            )}
          </>
        )}
      </div>
      {sealed && !changing && (
        <p className="text-[10px] text-muted-foreground">
          Sealed — this value can never be shown, only used or replaced.
        </p>
      )}
      {secret.value !== null && (
        <p className="text-[10px] text-muted-foreground">Hides itself in 30 seconds.</p>
      )}
      {error && <p className="text-[10px] text-amber-600 dark:text-amber-400">{error}</p>}
    </li>
  );
}

// ── Create from the current page ────────────────────────────────────────────

function CreateLoginForm({
  pageUrl,
  onCancel,
  onCreate,
}: {
  pageUrl: string | null;
  onCancel: () => void;
  onCreate: (input: {
    display_name: string;
    fields: { field_key: string; value: string }[];
    definition_key: string;
    login_urls: string[];
    browser_fill_enabled: boolean;
  }) => Promise<string | null>;
}) {
  const host = safeParseUrl(pageUrl)?.host ?? '';
  const normalized = normalizeLoginUrl(pageUrl);
  const [name, setName] = useState(host);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fillable = isFillablePageUrl(pageUrl);
  const canSave = name.trim().length > 0 && password.length > 0 && !busy;

  const submit = useCallback(async () => {
    setBusy(true);
    setError(null);
    const fields = [{ field_key: 'password', value: password }];
    if (username.trim()) fields.unshift({ field_key: 'username', value: username.trim() });
    const failure = await onCreate({
      display_name: name.trim(),
      fields,
      definition_key: WEBSITE_LOGIN_DEFINITION_KEY,
      login_urls: normalized && fillable ? [normalized] : [],
      browser_fill_enabled: normalized !== null && fillable,
    });
    // Drop the plaintext from this component the moment the request resolves,
    // whatever the outcome.
    setPassword('');
    setUsername('');
    setBusy(false);
    if (failure) setError(failure);
  }, [fillable, name, normalized, onCreate, password, username]);

  return (
    <div className="mx-2 mb-2 space-y-1.5 rounded-md border bg-card p-2">
      <div className="flex items-center gap-1.5">
        <Plus className="size-3 text-muted-foreground" />
        <span className="flex-1 text-xs font-medium">New login</span>
        <IconButton title="Cancel" onClick={onCancel}>
          <X className="size-3" />
        </IconButton>
      </div>
      <p className="text-[11px] text-muted-foreground">
        {fillable && normalized
          ? `Saved for ${host} and enabled for browser fill.`
          : 'This page is not an https destination, so no site will be attached.'}
      </p>
      <Input
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Name"
        className="h-7 text-xs"
      />
      <Input
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        placeholder="Username or email"
        autoComplete="off"
        className="h-7 text-xs"
      />
      <Input
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        placeholder="Password"
        type="password"
        autoComplete="new-password"
        className="h-7 text-xs"
      />
      {error && <p className="text-[11px] text-amber-600 dark:text-amber-400">{error}</p>}
      <Button
        size="sm"
        className="h-7 w-full text-xs"
        disabled={!canSave}
        onClick={() => void submit()}
      >
        {busy ? <Loader2 className="size-3 animate-spin" /> : 'Save to Vault'}
      </Button>
    </div>
  );
}

// ── Shared bits ─────────────────────────────────────────────────────────────

function IconButton({
  title,
  onClick,
  disabled,
  children,
}: {
  title: string;
  onClick: () => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      title={title}
      onClick={onClick}
      disabled={disabled}
      className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-50"
    >
      {children}
    </button>
  );
}
